import 'package:flutter/material.dart';
class TypingIndicator extends StatefulWidget { const TypingIndicator({super.key, required this.name}); final String name; @override State<TypingIndicator> createState() => _TypingIndicatorState(); }
class _TypingIndicatorState extends State<TypingIndicator> with SingleTickerProviderStateMixin { late final AnimationController controller; @override void initState() { super.initState(); controller = AnimationController(vsync: this, duration: const Duration(milliseconds: 900))..repeat(reverse: true); } @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) => FadeTransition(opacity: controller, child: Text('${widget.name} يكتب...', style: Theme.of(context).textTheme.bodySmall)); }
